// Applies CoastGuard 360's Android settings to the project generated by
// `flutter create`.
//
// Usage, from the /mobile folder (after `flutter create`, see the error text
// the script prints if android/ is missing):
//   dart tool/configure_android.dart
//
// IMPORTANT
//   * This script EDITS ANDROID MANIFESTS IN PLACE and makes NO BACKUP.
//     Commit first, run it, then inspect:  git diff -- android
//   * It runs only in a project whose pubspec.yaml has
//     `name: coastguard360_mobile`, and refuses to write through symbolic
//     links under android/.
//   * All inputs are validated, and every edit is computed and re-validated
//     in memory, before ANY file is written. Unexpected or malformed
//     manifests stop the run with an ERROR and nothing is changed.
//   * Safe to run repeatedly (idempotent).
//
// What it does
//   * Main manifest (android/app/src/main/AndroidManifest.xml):
//       - adds <uses-permission> for INTERNET, ACCESS_FINE_LOCATION and
//         ACCESS_COARSE_LOCATION when missing (XML comments are ignored;
//         a tools:node="remove" directive for one of them is an ERROR);
//       - adds android:allowBackup="false" (the JWT lives in secure storage).
//         If allowBackup already exists with another value it is NOT changed
//         and a WARNING is printed.
//   * Debug-only cleartext HTTP: installs
//     android/app/src/debug/res/xml/network_security_config.xml (cleartext to
//     10.0.2.2 and 172.20.10.2 ONLY) and references it from the DEBUG manifest.
//     Profile and release builds get NO cleartext allowance; a profile build
//     (flutter run --profile) cannot use an http:// API_BASE_URL.
//     If the main or debug manifest already references a different
//     networkSecurityConfig, nothing is attached or installed and a WARNING
//     is printed. An existing, differing XML file is never overwritten.
//   * Prints the minSdk setting for review (it is not changed).
import 'dart:io';

const _projectName = 'coastguard360_mobile';
const _mainManifest = 'android/app/src/main/AndroidManifest.xml';
const _debugManifest = 'android/app/src/debug/AndroidManifest.xml';
const _debugXmlDir = 'android/app/src/debug/res/xml';
const _xmlName = 'network_security_config.xml';
const _xmlTemplate = 'tool/android/$_xmlName';
const _networkRef = '@xml/network_security_config';
const _networkAttr =
    '<application android:networkSecurityConfig="$_networkRef"/>';

const _permissions = <String>[
  'android.permission.INTERNET',
  'android.permission.ACCESS_FINE_LOCATION',
  'android.permission.ACCESS_COARSE_LOCATION',
];

// <uses-permission ... android:name="X" ...>  (single or double quotes).
// The mandatory whitespace after the tag name excludes <permission> and
// <uses-permission-sdk-23>.
final _usesPermission = RegExp(
    r'''<uses-permission\s[^>]*?android:name\s*=\s*(?:"([^"]*)"|'([^']*)')[^>]*>''');
final _removalDirective = RegExp(r'''tools:node\s*=\s*(?:"|')\s*remove''');
final _allowBackup =
    RegExp(r'''android:allowBackup\s*=\s*(?:"([^"]*)"|'([^']*)')''');
final _networkConfigAttr =
    RegExp(r'''android:networkSecurityConfig\s*=\s*(?:"([^"]*)"|'([^']*)')''');

final _warnings = <String>[];

Never _fail(String message) {
  stderr.writeln('ERROR: $message');
  exit(1);
}

void _warn(String message) {
  _warnings.add(message);
  stderr.writeln('WARNING: $message');
}

void main() {
  try {
    _run();
  } on FileSystemException catch (e) {
    _fail('File operation failed: ${e.message}'
        '${e.path?.isEmpty ?? true ? '' : ' (${e.path})'}. Nothing further was done.');
  }
}

void _run() {
  _checkProject();

  // Phase 1: validate and compute every edit in memory. Nothing is written.
  final mainPlan = _planMainManifest();
  final debugPlan =
      _planDebugManifest(mainConflict: mainPlan.networkConfigConflict);
  final xmlPlan = _planNetworkXml(install: debugPlan.installXml);

  // Phase 2: write.
  if (mainPlan.newText == null) {
    print('Main manifest: already configured.');
  } else {
    File(_mainManifest).writeAsStringSync(mainPlan.newText!);
    print('Main manifest: updated '
        '(${mainPlan.permissionsAdded} permission(s) added'
        '${mainPlan.backupAdded ? ', allowBackup=false added' : ''}).');
  }
  if (debugPlan.newText != null) {
    final file = File(_debugManifest);
    file.parent.createSync(recursive: true);
    file.writeAsStringSync(debugPlan.newText!);
    print('Debug manifest: network security config attached.');
  }
  if (xmlPlan != null) {
    final file = File('$_debugXmlDir/$_xmlName');
    file.parent.createSync(recursive: true);
    file.writeAsStringSync(xmlPlan);
    print('Network security config: installed at ${file.path}.');
  }

  _reportMinSdk();
  if (_warnings.isNotEmpty) {
    stderr.writeln('\nCompleted with ${_warnings.length} warning(s):');
    for (final w in _warnings) {
      stderr.writeln(' - $w');
    }
  }
  print('Done. Review with: git diff -- android');
}

// ---------------------------------------------------------------- guards

void _checkProject() {
  final pubspec = File('pubspec.yaml');
  if (!pubspec.existsSync()) {
    _fail('Run this from the /mobile folder (pubspec.yaml not found).');
  }
  final namePattern =
      RegExp('^name:\\s*$_projectName\\s*(#.*)?\$', multiLine: true);
  if (!namePattern.hasMatch(pubspec.readAsStringSync())) {
    _fail('pubspec.yaml does not declare "name: $_projectName"; refusing to '
        'modify a different project.');
  }

  final androidType = FileSystemEntity.typeSync('android', followLinks: false);
  if (androidType == FileSystemEntityType.notFound) {
    _fail('android/ not found. First run:\n'
        '  flutter create --platforms=android '
        '--project-name $_projectName --org com.coastguard360 .');
  }
  if (androidType != FileSystemEntityType.directory) {
    _fail('android is a symbolic link or not a directory; refusing to '
        'write through it.');
  }
  for (final path in [
    _mainManifest,
    _debugManifest,
    '$_debugXmlDir/$_xmlName',
  ]) {
    _assertNoSymlink(path);
  }

  if (!File(_xmlTemplate).existsSync()) _fail('$_xmlTemplate not found.');
  if (!File(_mainManifest).existsSync()) {
    _fail(
        '$_mainManifest not found. Was android/ generated by flutter create?');
  }
}

void _assertNoSymlink(String path) {
  var current = '';
  for (final part in path.split('/')) {
    current = current.isEmpty ? part : '$current/$part';
    if (FileSystemEntity.isLinkSync(current)) {
      _fail('$current is a symbolic link; refusing to write through it.');
    }
  }
}

// ------------------------------------------------------------ XML helpers

/// Replaces complete XML comments with spaces of equal length, so regex
/// matches on the result have the same indexes as in the original text.
String _mask(String text) => text.replaceAllMapped(
    RegExp(r'<!--.*?-->', dotAll: true), (m) => ' ' * m.group(0)!.length);

/// Checks the manifest has the recognized Flutter shape: exactly one
/// <manifest ...xmlns:android...> element with one closing tag, at most one
/// <application>, placed inside <manifest>.
({String masked, int closeStart, RegExpMatch? app}) _parseManifest(
    String label, String text,
    {required bool needApplication}) {
  Never bad(String reason) => _fail('$label is not in the expected '
      'Flutter-generated form ($reason). No files were changed.');

  final masked = _mask(text);
  if (masked.contains('<!--')) bad('unterminated XML comment');
  final opens = RegExp(r'<manifest[\s>]').allMatches(masked).toList();
  final closes = RegExp(r'</manifest\s*>').allMatches(masked).toList();
  if (opens.length != 1) {
    bad('expected exactly one <manifest> element, found ${opens.length}');
  }
  if (closes.length != 1) {
    bad('expected exactly one </manifest> tag, found ${closes.length}');
  }
  final openEnd = masked.indexOf('>', opens.first.start);
  if (openEnd < 0 || masked[openEnd - 1] == '/') {
    bad('<manifest> is self-closing or unterminated');
  }
  if (!masked
      .substring(opens.first.start, openEnd)
      .contains('xmlns:android=')) {
    bad('missing xmlns:android declaration');
  }
  if (closes.first.start < openEnd) bad('closing tag precedes opening tag');

  final apps = RegExp(r'<application[\s/>]').allMatches(masked).toList();
  if (apps.length > 1) bad('more than one <application> element');
  if (needApplication && apps.isEmpty) bad('no <application> element');
  final app = apps.isEmpty ? null : apps.first;
  if (app != null && (app.start < openEnd || app.start > closes.first.start)) {
    bad('<application> is outside <manifest>');
  }
  return (masked: masked, closeStart: closes.first.start, app: app);
}

/// Text of the opening <application ...> tag (comments already masked).
String _applicationTag(String label, String masked, RegExpMatch app) {
  final end = masked.indexOf('>', app.start);
  if (end < 0) _fail('$label has an unterminated <application> tag.');
  return masked.substring(app.start, end + 1);
}

({Set<String> present, Set<String> removed}) _scanPermissions(String masked) {
  final present = <String>{};
  final removed = <String>{};
  for (final e in _usesPermission.allMatches(masked)) {
    final name = e.group(1) ?? e.group(2)!;
    if (_removalDirective.hasMatch(e.group(0)!)) {
      removed.add(name);
    } else {
      present.add(name);
    }
  }
  return (present: present, removed: removed);
}

// ------------------------------------------------------------------ plans

({
  String? newText,
  int permissionsAdded,
  bool backupAdded,
  bool networkConfigConflict
}) _planMainManifest() {
  final text = File(_mainManifest).readAsStringSync();
  final m = _parseManifest(_mainManifest, text, needApplication: true);
  final app = m.app!;
  final appTag = _applicationTag(_mainManifest, m.masked, app);

  // Permissions: comments, <permission> and removal directives never count
  // as an existing declaration.
  final scan = _scanPermissions(m.masked);
  for (final p in _permissions) {
    if (scan.removed.contains(p)) {
      _fail('$_mainManifest removes $p with a tools:node directive. '
          'Resolve this manually; no files were changed.');
    }
  }
  final missing = _permissions.where((p) => !scan.present.contains(p)).toList();

  // allowBackup: never overwrite an existing value, but never hide it either.
  final backup = _allowBackup.firstMatch(appTag);
  final addBackup = backup == null;
  if (backup != null) {
    final value = backup.group(1) ?? backup.group(2)!;
    if (value != 'false') {
      _warn('android:allowBackup is "$value" in $_mainManifest and was left '
          'unchanged. Set it to "false" (the JWT is stored on the device) or '
          'confirm this with the team.');
    }
  }

  // A pre-existing networkSecurityConfig in the main manifest would clash
  // with the debug overlay (and would leak into release builds).
  final existingNet = _networkConfigAttr.firstMatch(appTag);
  if (existingNet != null) {
    final value = existingNet.group(1) ?? existingNet.group(2)!;
    _warn('$_mainManifest already sets networkSecurityConfig to "$value". '
        'The debug-only cleartext config was NOT attached or installed.');
  }

  // Apply edits from the end of the file backwards so indexes stay valid.
  var out = text;
  if (addBackup) {
    final at = app.start + '<application'.length;
    out = out.replaceRange(at, at, '\n        android:allowBackup="false"');
  }
  if (missing.isNotEmpty) {
    final lines = missing
        .map((p) => '<uses-permission android:name="$p"/>')
        .join('\n    ');
    out = out.replaceRange(app.start, app.start, '$lines\n    ');
  }
  if (out == text) {
    return (
      newText: null,
      permissionsAdded: 0,
      backupAdded: false,
      networkConfigConflict: existingNet != null
    );
  }

  // Re-validate the result before anything is written.
  final after = _parseManifest(_mainManifest, out, needApplication: true);
  final afterScan = _scanPermissions(after.masked);
  final afterTag = _applicationTag(_mainManifest, after.masked, after.app!);
  if (!_permissions.every(afterScan.present.contains) ||
      !_allowBackup.hasMatch(afterTag)) {
    _fail('Internal check failed after editing $_mainManifest. '
        'No files were changed.');
  }
  return (
    newText: out,
    permissionsAdded: missing.length,
    backupAdded: addBackup,
    networkConfigConflict: existingNet != null
  );
}

({String? newText, bool installXml}) _planDebugManifest(
    {required bool mainConflict}) {
  if (mainConflict) return (newText: null, installXml: false);

  final file = File(_debugManifest);
  if (!file.existsSync()) {
    const text =
        '<manifest xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '    <uses-permission android:name="android.permission.INTERNET"/>\n'
        '    $_networkAttr\n'
        '</manifest>\n';
    _parseManifest(_debugManifest, text, needApplication: false);
    return (newText: text, installXml: true);
  }

  final text = file.readAsStringSync();
  final m = _parseManifest(_debugManifest, text, needApplication: false);

  if (m.app != null) {
    final tag = _applicationTag(_debugManifest, m.masked, m.app!);
    final net = _networkConfigAttr.firstMatch(tag);
    if (net == null) {
      _fail('$_debugManifest already has an <application> element without '
          'networkSecurityConfig. Add android:networkSecurityConfig='
          '"$_networkRef" to it manually; no files were changed.');
    }
    final value = net.group(1) ?? net.group(2)!;
    if (value == _networkRef) {
      print('Debug manifest: already configured.');
      return (newText: null, installXml: true);
    }
    _warn('$_debugManifest already references networkSecurityConfig '
        '"$value". It was left unchanged and the script\'s XML was NOT '
        'installed.');
    return (newText: null, installXml: false);
  }

  final out =
      text.replaceRange(m.closeStart, m.closeStart, '    $_networkAttr\n');
  final after = _parseManifest(_debugManifest, out, needApplication: false);
  final tag = _applicationTag(_debugManifest, after.masked, after.app!);
  final net = _networkConfigAttr.firstMatch(tag);
  if (net == null || (net.group(1) ?? net.group(2)) != _networkRef) {
    _fail('Internal check failed after editing $_debugManifest. '
        'No files were changed.');
  }
  return (newText: out, installXml: true);
}

/// Returns the XML to write, or null when nothing should be written.
String? _planNetworkXml({required bool install}) {
  if (!install) {
    print('Network security config: skipped (see warnings).');
    return null;
  }
  final source = File(_xmlTemplate).readAsStringSync();
  final target = File('$_debugXmlDir/$_xmlName');
  if (target.existsSync()) {
    if (target.readAsStringSync() == source) {
      print('Network security config: already installed.');
    } else {
      _warn('${target.path} exists and differs from $_xmlTemplate; '
          'left untouched.');
    }
    return null;
  }
  return source;
}

void _reportMinSdk() {
  for (final path in [
    'android/app/build.gradle.kts',
    'android/app/build.gradle',
  ]) {
    final file = File(path);
    if (!file.existsSync()) continue;
    final match = RegExp(r'minSdk(?:Version)?\s*=?\s*([^\n]+)')
        .firstMatch(file.readAsStringSync());
    print('minSdk in $path: ${match?.group(1)?.trim() ?? 'not found'} '
        '(left unchanged; flutter_secure_storage needs >= 19, '
        '>= 23 for encrypted preferences).');
    return;
  }
  print('minSdk: no app build.gradle(.kts) found.');
}
